(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.TangentLineLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){return String(Number(x.toFixed(6))).replace('.','{,}');}
const forms={square:String.raw`f(x)=x^2`,cube:String.raw`f(x)=x^3`,absolute:String.raw`f(x)=|x|`};let grid='';for(let x=-2;x<=2;x++){const p=core.point(x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="330" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="352" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(let y=-8;y<=8;y+=2){const p=core.point(0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}$('#tangent-grid').innerHTML=grid;
function line(slope,a,fa){if(slope===null)return '';const p=core.point(-2,fa+slope*(-2-a)),q=core.point(2,fa+slope*(2-a));return `M${p.x} ${p.y}L${q.x} ${q.y}`;}
function lineTex(slope,b){if(slope===0)return 'y='+fmt(b);return 'y='+(slope===1?'':slope===-1?'-':fmt(slope))+'x'+(b===0?'':(b>0?'+':'-')+fmt(Math.abs(b)));}
function draw(){const kind=$('#tangent-kind').value,a=Number($('#tangent-a').value),index=Number($('#tangent-step').value),distance=core.distances[index],direction=Number($('#tangent-direction').value),zero=$('#tangent-zero').checked,h=zero?0:direction*distance,t=core.measure(kind,a,h);$('#step-output').value=String(zero?0:distance).replace('.',',');$('#tangent-step').setAttribute('aria-valuetext',String(distance));$('#tangent-step').disabled=zero;$('#tangent-direction').disabled=zero;math($('#tangent-formula'),forms[kind]+String.raw`,\quad a=${a},\quad h=${fmt(h)}`);$('#function-curve').setAttribute('d',core.curve(kind).map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));$('#secant-line').setAttribute('d',line(t.slope,a,t.fa));$('#tangent-line').setAttribute('d',line(t.derivative,a,t.fa));for(const [id,x,y]of [['fixed-point',a,t.fa],['moving-point',t.b,t.fb]]){const p=core.point(x,y);$('#'+id).setAttribute('cx',p.x);$('#'+id).setAttribute('cy',p.y);}$('#moving-point').setAttribute('visibility',zero?'hidden':'visible');math($('#tangent-values'),String.raw`\begin{aligned}P&=(${fmt(a)}\,;\,${fmt(t.fa)})\\Q&=(${fmt(t.b)}\,;\,${fmt(t.fb)})\\m_h&`+(t.slope===null?String.raw`\text{ tidak terdefinisi karena }h=0`:'='+String.raw`\frac{f(a+h)-f(a)}h\approx${fmt(t.slope)}`)+String.raw`\end{aligned}`);$('#tangent-table').innerHTML=core.distances.map((d,i)=>`<tr ${!zero&&i===index?'class="tangent-selected"':''}>${[-d,core.measure(kind,a,-d).slope,d,core.measure(kind,a,d).slope].map(v=>`<td><span data-tex="${fmt(v)}"></span></td>`).join('')}</tr>`).join('');math($('#derivative-result'),t.derivative===null?String.raw`\text{Turunan dua sisi di }a=${a}\text{ tidak ada.}`:String.raw`\begin{aligned}f'(${a})&=${fmt(t.derivative)}\\\text{Garis singgung: }&${lineTex(t.derivative,t.fa-t.derivative*a)}\end{aligned}`);$('#tangent-note').textContent=(zero?'Perubahan tepat nol membuat kemiringan sekan tidak terdefinisi. Nilai turunan, jika ada, tetap diperoleh dari limit perubahan bukan nol. ':'Kemiringan sekan memakai dua titik berbeda. Tabel membandingkan pendekatan dari kedua sisi. ')+(t.derivative===null?'Pada sudut tajam nilai mutlak di nol, sisi kiri menuju negatif satu dan sisi kanan satu. Tidak ada satu kemiringan singgung berhingga yang sama.':kind==='cube'&&a===0?'Kedua kemiringan mendekati nol. Garis singgung mendatar ini dipotong kurva pangkat tiga; memotong kurva tidak membatalkan sifat singgungnya.':`Kedua arah mendekati kemiringan ${t.derivative}. Garis singgung melalui titik tetap dan mempunyai kemiringan tersebut.`)+' Nilai desimal pada aktivitas dibulatkan hingga enam angka di belakang koma.';$('#tangent-plot').setAttribute('aria-label',`Grafik ${kind==='square'?'kuadrat':kind==='cube'?'pangkat tiga':'nilai mutlak'}. Titik tetap (${a}, ${t.fa}), perubahan masukan ${h}. ${t.slope===null?'Kemiringan sekan tidak terdefinisi.':'Kemiringan sekan sekitar '+t.slope.toFixed(6)+'.'} ${t.derivative===null?'Turunan dua sisi tidak ada; garis singgung berkemiringan sama tidak ditampilkan.':'Kemiringan singgung '+t.derivative+'.'}`);}
for(const id of ['tangent-kind','tangent-a','tangent-direction','tangent-step','tangent-zero'])$('#'+id).addEventListener('input',draw);function preset(kind,a){$('#tangent-kind').value=kind;$('#tangent-a').value=a;$('#tangent-direction').value=1;$('#tangent-step').value=1;$('#tangent-zero').checked=false;draw();}$('#try-corner').addEventListener('click',()=>preset('absolute',0));$('#try-crossing').addEventListener('click',()=>preset('cube',0));$('#reset-tangent').addEventListener('click',()=>preset('square',1));draw();
const questions=[{tex:String.raw`f(x)=x^2,\quad a=1`,prompt:'Berapa limit kemiringan sekan ketika perubahan masukan menuju nol?',n:2,d:1,hint:'Untuk titik tetap di satu, kemiringan sekan sama dengan dua ditambah perubahan masukan.',why:'Dua ditambah h mendekati dua saat h mendekati nol. Turunan di satu adalah dua.'},{tex:String.raw`f(x)=x^3,\quad a=0`,prompt:'Berapa kemiringan garis singgung di nol?',n:0,d:1,hint:'Kemiringan sekan di titik ini adalah h kuadrat.',why:'H kuadrat mendekati nol dari kedua sisi. Maka garis singgungnya mendatar dengan kemiringan nol.'},{tex:String.raw`f(1)=1,\quad f'(1)=2,\quad y=2x+c`,prompt:'Berapa c agar garis ini menyinggung fungsi di titik tersebut?',n:-1,d:1,hint:'Masukkan titik satu, satu ke persamaan garis.',why:'Satu sama dengan dua kali satu ditambah c, sehingga c adalah negatif satu. Garisnya y sama dengan dua x dikurangi satu.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis bilangan yang diminta, misalnya 2, 0, atau -1.':'Belum tepat. Periksa titik tetap, limit kemiringan, dan persamaan garisnya.');}));
const choices=[{tex:String.raw`f(x)=|x|,\quad a=0`,prompt:'Apa yang terjadi pada turunan dua sisi di nol?',options:[{text:'Ada dan bernilai nol karena fungsi kontinu.'},{text:'Tidak ada, karena kemiringan dari kiri dan kanan berbeda.'},{text:'Ada dan bernilai satu dari kedua sisi.'}],answer:1,why:'Kemiringan sekan dari kiri negatif satu dan dari kanan satu. Kekontinuan fungsi di nol tidak menyamakan kedua kemiringan.'},{tex:String.raw`\frac{f(a+h)-f(a)}h,\quad h=0`,prompt:'Bagaimana hubungan pecahan ini dengan turunan?',options:[{text:'Pecahan tidak terdefinisi; turunan dicari melalui limit saat h mendekati nol.'},{text:'Pecahan selalu nol, sehingga turunan selalu nol.'},{text:'Boleh membagi dengan nol jika kedua titik berimpit.'}],answer:0,why:'Turunan adalah limit kemiringan untuk perubahan bukan nol. Memasukkan nol langsung membuat pembaginya nol dan bukan cara menghitung turunan.'},{tex:String.raw`f(x)=x^3,\quad y=0\text{ di titik }(0,0)`,prompt:'Apakah garis ini dapat menjadi singgung meskipun kurva melintasinya?',options:[{text:'Tidak, singgung tidak pernah dipotong kurva.'},{text:'Tidak, garis mendatar selalu garis sekan.'},{text:'Ya, karena limit kemiringan sekan di nol adalah nol.'}],answer:2,why:'Definisi singgung di sini berasal dari limit kemiringan. Pada pangkat tiga di nol, kemiringannya nol dan kurva melewati garis singgung dari bawah ke atas.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-tangent-line-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-tangent-line-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();